select.if:
select * from (
SELECT B.BOOKSET_ID as prodId, C.BOOKSET_NAME as prodName,
DATE_FORMAT(D.MDATE,'%Y-%m-%d') as mDate, IFNULL(T1.FINPROD_TYPE,T2.FINPROD_TYPE) AS finprodType, A.BUSI_ID as finprodId, IFNULL(T1.FINPROD_NAME,T2.FINPROD_ID) AS finprodName , A.SUBJECT_NO as subjectNo, E.SUBJECT_NAME as subjectName, CASE WHEN SUM( (case when A.CD_FLAG = 'D' then 1 else -1 end) * A.HAPPEN_AMT) > 0 THEN 'D' ELSE 'C' END as balFlag, --余额方向 ABS(SUM( (case when A.CD_FLAG = 'D' then 1 else -1 end) * A.HAPPEN_AMT)) AS oAmt
FROM BOK_VOUCH_DETAIL A JOIN BOK_VOUCH_MAIN B ON A.VOUCH_NUM = B.VOUCH_NUM JOIN BOK_BOOKSET C ON B.BOOKSET_ID = C.BOOKSET_ID JOIN FIN_PRODUCT D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID JOIN BOK_SUBJECT E ON A.SUBJECT_NO = E.SUBJECT_NO LEFT JOIN FIN_PRODUCT T1 ON A.BUSI_ID = T1.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT T2 ON A.BUSI_ID = T2.FINPROD_ID
WHERE E.BASE_SUBJECT_NATURE IN
#{subject}
AND A.HAPPEN_DATE <= STR_TO_DATE(#{qrydate},'%Y-%m-%d') AND D.MDATE >= STR_TO_DATE(#{qrydate},'%Y-%m-%d')
AND B.BOOKSET_ID =#{queryDto.booksetId}
AND A.BUSI_ID IN
null) or A.BUSI_ID in (
#{assets}
and A.BUSI_ID not IN
#{noNull}
AND IFNULL(T1.FINPROD_TYPE,T2.FINPROD_TYPE) IN
#{fintype}
GROUP BY B.BOOKSET_ID, C.BOOKSET_NAME, D.MDATE, T1.FINPROD_TYPE, T2.FINPROD_TYPE, A.BUSI_ID, A.SUBJECT_NO, E.SUBJECT_NAME, T1.FINPROD_NAME, T2.FINPROD_ID HAVING SUM((case when A.CD_FLAG = 'D' then 1 else -1 end) * A.HAPPEN_AMT) != 0
)

mapper.select:
SELECT B.BOOKSET_ID as prodId, C.BOOKSET_NAME as prodName,
DATE_FORMAT(D.MDATE,'%Y-%m-%d') as mDate, IFNULL(T1.FINPROD_TYPE,T2.FINPROD_TYPE) AS finprodType, A.BUSI_ID as finprodId, IFNULL(T1.FINPROD_NAME,T2.FINPROD_ID) AS finprodName , A.SUBJECT_NO as subjectNo, E.SUBJECT_NAME as subjectName, CASE WHEN SUM((case when A.CD_FLAG = 'D' then 1 else -1 end) * A.HAPPEN_AMT) > 0 THEN 'D' ELSE 'C' END as balFlag, --余额方向 ABS(SUM((case when A.CD_FLAG = 'D' then 1 else -1 end) * A.HAPPEN_AMT)) AS oAmt
FROM BOK_VOUCH_DETAIL A JOIN BOK_VOUCH_MAIN B ON A.VOUCH_NUM = B.VOUCH_NUM JOIN BOK_BOOKSET C ON B.BOOKSET_ID = C.BOOKSET_ID JOIN FIN_PRODUCT D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID JOIN BOK_SUBJECT E ON A.SUBJECT_NO = E.SUBJECT_NO and e.bookset_id=c.bookset_id_tmpl LEFT JOIN FIN_PRODUCT T1 ON A.BUSI_ID = T1.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT T2 ON A.BUSI_ID = T2.FINPROD_ID WHERE E.BASE_SUBJECT_NATURE IN
#{subject}
AND A.HAPPEN_DATE <= STR_TO_DATE(#{qrydate},'%Y-%m-%d') AND D.MDATE >= STR_TO_DATE(#{qrydate},'%Y-%m-%d') AND B.BOOKSET_ID =#{booksetId} AND A.BUSI_ID IN
#{assets}
and A.BUSI_ID not IN
#{noNull}
AND IFNULL(T1.FINPROD_TYPE,T2.FINPROD_TYPE) IN
#{fintype}
GROUP BY B.BOOKSET_ID, C.BOOKSET_NAME, D.MDATE, T1.FINPROD_TYPE, T2.FINPROD_TYPE, A.BUSI_ID, A.SUBJECT_NO, E.SUBJECT_NAME, T1.FINPROD_NAME, T2.FINPROD_ID HAVING SUM((case when A.CD_FLAG = 'D' then 1 else -1 end) * A.HAPPEN_AMT) != 0

SELECT B.BOOKSET_ID, A.BUSI_ID FROM BOK_VOUCH_DETAIL A JOIN BOK_VOUCH_MAIN B ON A.VOUCH_NUM = B.VOUCH_NUM JOIN BOK_BOOKSET C ON B.BOOKSET_ID = C.BOOKSET_ID JOIN FIN_PRODUCT D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID AND D.FINPROD_TYPE = 'F16' AND D.MDATE >= STR_TO_DATE(#{qrydate},'%Y-%m-%d')
JOIN FIN_PRODUCT T1 ON A.BUSI_ID = T1.FINPROD_ID AND T1.FINPROD_TYPE IN
#{finprodtype}
JOIN TRD_PRODUCT_DEAL T2 ON B.TRADE_ID = T2.TRADE_ID AND T2.FINPROD_TYPE IN
#{finprodtype}
JOIN BOK_SUBJECT E ON A.SUBJECT_NO = E.SUBJECT_NO and e.bookset_id=c.bookset_id_tmpl WHERE E.BASE_SUBJECT_NATURE IN
#{subjectNature}
AND A.HAPPEN_DATE <= STR_TO_DATE(#{qrydate},'%Y-%m-%d')
AND B.BOOKSET_ID IN
#{booksetId}
GROUP BY B.BOOKSET_ID, A.BUSI_ID HAVING SUM((case when A.CD_FLAG = 'D' then 1 else -1 end) * A.HAPPEN_AMT) <= 0

SELECT B.BOOKSET_ID, A.BUSI_ID FROM BOK_VOUCH_DETAIL A JOIN BOK_VOUCH_MAIN B ON A.VOUCH_NUM = B.VOUCH_NUM JOIN BOK_BOOKSET C ON B.BOOKSET_ID = C.BOOKSET_ID JOIN FIN_PRODUCT D ON C.ACCT_SUBJECT_ID = D.FINPROD_ID AND D.FINPROD_TYPE = 'F16'
AND D.MDATE >= STR_TO_DATE(#{qrydate},'%Y-%m-%d') LEFT JOIN FIN_PRODUCT T1 ON A.BUSI_ID = T1.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT T2 ON A.BUSI_ID = T2.FINPROD_ID
JOIN BOK_SUBJECT E ON A.SUBJECT_NO = E.SUBJECT_NO and e.bookset_id=c.bookset_id_tmpl WHERE E.BASE_SUBJECT_NATURE IN
#{subjectNature}
AND A.HAPPEN_DATE <= STR_TO_DATE(#{qrydate},'%Y-%m-%d')
AND B.BOOKSET_ID IN
#{booksetId}
AND IFNULL(T1.FINPROD_TYPE,T2.FINPROD_TYPE) IN
#{finprodtype}
GROUP BY B.BOOKSET_ID, A.BUSI_ID,A.HAPPEN_AMT HAVING SUM((case when A.CD_FLAG = 'D' then 1 else -1 end) * A.HAPPEN_AMT) = 0
